import assert from 'node:assert/strict'
import { createRequire } from 'node:module'

const { ArgumentParser } = createRequire(import.meta.url)('../../lib/argparse.js')

function parse (type, value) {
  const parser = new ArgumentParser({ exit_on_error: false })
  parser.add_argument('--v', { type })
  return parser.parse_args([`--v=${value}`]).v
}

// Python's float() spellings the port must accept.
assert.equal(parse('float', 'inf'), Infinity)
assert.equal(parse('float', '-Infinity'), -Infinity)
assert.ok(Number.isNaN(parse('float', 'nan')))
assert.equal(parse('float', '1_000'), 1000)
// And one it must reject.
assert.throws(() => parse('float', '1,5'))
// int('-0') is 0, never negative zero.
assert.ok(Object.is(parse('int', '-0'), 0))

console.log('visible check passed')
